{"success": true, "data": {"stdout": "    parser = argparse.ArgumentParser(description="Execute structured pruning on Qwen2.5 model (GQA-group granularity)")
    parser.add_argument("--model_path", type=str, required=True, help="Path to pretrained model")
    parser.add_argument("--importance_path", type=str, default=None, help="Path to importance scores .pt (required for standard/rasp/rasp-rlvr/gradient)")
    parser.add_argument("--cka_path", type=str, default=None, help="Path to CKA overlap scores .pt")
    parser.add_argument("--mode", type=str, choices=["standard", "rasp", "rasp-rlvr", "magnitude", "gradient", "random", "cka_only"], required=True)
    parser.add_argument("--sparsity", type=float, default=0.35, help="Target sparsity ratio")
    parser.add_argument("--alpha", type=float, default=1.0, help="RASP alpha parameter")
    parser.add_argument("--output_path", type=str, required=True, help="Output path for pruned model")
    parser.add_argument("--seed", type=int, default=42)
    parser.add_argument("--dtype", type=str, default="bfloat16", choices=["float16", "bfloat16", "float32"])
    parser.add_argument("--skip_attention", action="store_true", default=False, help="Only prune MLP groups, skip attention groups")
    args = parser.parse_args()

    set_seed(args.seed)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    dtype_map = {"float16": torch.float16, "bfloat16": torch.bfloat16, "float32": torch.float32}
    torch_dtype = dtype_map[args.dtype]

    logger.info(f"Loading model from {args.model_path}")
    tokenizer = AutoTokenizer.from_pretrained(args.model_path, trust_remote_code=True)
    model = AutoModelForCausalLM.from_pretrained(
        args.model_path,
        torch_dtype=torch_dtype,
        device_map="cpu",
        trust_remote_code=True,
    )

    original_params = count_parameters(model)
    logger.info(f"Original model parameters: {original_params:,}")

    # Load scores based on mode
    needs_importance = args.mode in ("standard", "rasp", "rasp-rlvr", "gradient")
    needs_cka = args.mode in ("rasp", "rasp-rlvr", "cka_only")

    if needs_importance:
        if args.importance_path is None:
            raise ValueError(f"--importance_path required for {args.mode} mode")
        importance_data = torch.load(args.importance_path, map_location="cpu", weights_only=True)
        attn_importance = importance_data["attn_importance"]
        mlp_importance = importance_data["mlp_importance"]

    if needs_cka:
        if args.cka_path is None:
            raise ValueError(f"--cka_path required for {args.mode} mode")
        cka_data = torch.load(args.cka_path, map_location="cpu", weights_only=True)
        attn_overlap = cka_data["attn_overlap"]
        mlp_overlap = cka_data["mlp_overlap"]

    if args.mode == "rasp":
        attn_scores = {}
        for k in attn_importance:
            attn_scores[k] = attn_importance[k].float() * (1.0 - attn_overlap[k].float()).pow(args.alpha)
        mlp_scores = {}
        for k in mlp_importance:
            mlp_scores[k] = mlp_importance[k].float() * (1.0 - mlp_overlap[k].float()).pow(args.alpha)
        logger.info(f"Using RASP scoring with alpha={args.alpha}")
    elif args.mode == "rasp-rlvr":
        attn_scores = {}
        for k in attn_importance:
            attn_scores[k] = attn_importance[k].float() * attn_overlap[k].float().pow(args.alpha)
        mlp_scores = {}
        for k in mlp_importance:
            mlp_scores[k] = mlp_importance[k].float() * mlp_overlap[k].float().pow(args.alpha)
        logger.info(f"Using RASP-RLVR scoring with alpha={args.alpha}")
    elif args.mode in ("standard", "gradient"):
        attn_scores = {k: v.float() for k, v in attn_importance.items()}
        mlp_scores = {k: v.float() for k, v in mlp_importance.items()}
        logger.info(f"Using {args.mode} (Taylor importance) scoring")
    elif args.mode == "magnitude":
        logger.info("Computing magnitude scores from model weights...")
        attn_scores, mlp_scores = compute_magnitude_scores(model)
        logger.info("Using magnitude-only scoring")
    elif args.mode == "random":
        n_layers_cfg = model.config.num_hidden_layers
        n_kv_cfg = model.config.num_key_value_heads
        n_mlp_cfg = model.config.num_attention_heads
        torch.manual_seed(42)
        attn_scores = {i: torch.rand(n_kv_cfg) for i in range(n_layers_cfg)}
        mlp_scores = {i: torch.rand(n_mlp_cfg) for i in range(n_layers_cfg)}
        logger.info("Using random scoring (seed=42)")
    elif args.mode == "cka_only":
        attn_scores = {}
        for k in attn_overlap:
            attn_scores[k] = (1.0 - attn_overlap[k].float())
        mlp_scores = {}
        for k in mlp_overlap:
            mlp_scores[k] = (1.0 - mlp_overlap[k].float())
        logger.info("Using CKA-only scoring (score = 1 - overlap)")

    # Architecture parameters
    config = model.config
    n_layers = config.num_hidden_layers
